<section class="page-hero shell account-hero"><p class="kicker"><?=e($passport['public_code'])?></p><h1><?=e($passport['name'])?></h1><p><?=e($passport['material'])?> · <?=e($passport['finish'])?></p></section><section class="section section-tight shell passport-detail-grid"><div class="passport-card"><img src="<?=e(image_url($passport['image']))?>" alt="<?=e($passport['name'])?>"><div><h2>Ownership record</h2><dl><dt>Warranty</dt><dd><?=e($passport['warranty']['status'])?> · <?=e(substr((string)$passport['warranty']['expires_at'],0,10))?></dd><dt>Care</dt><dd><?=e($passport['care'])?></dd><dt>Fingerprint</dt><dd><code><?=e(substr($passport['design_fingerprint'],0,18))?>…</code></dd></dl><?php if(!empty($passport['qr_file'])):?><img class="passport-qr" src="<?=e(asset('passports/'.$passport['qr_file']))?>" alt="QR code for public product passport"><?php endif;?></div></div><aside class="service-panel"><p class="kicker">Care & service</p><h2>Request support</h2><form method="post" action="<?=e(url('/account/passports/'.$passport['guid'].'/service'))?>"><?=csrf_field()?><label>Request type<select name="type"><option>CARE</option><option>WARRANTY</option><option>REPAIR</option><option>PARTS</option></select></label><label>What do you need?<textarea name="message" rows="5" minlength="10" required></textarea></label><button class="btn dark">Open service request</button></form><?php if($cases):?><h3>Previous requests</h3><?php foreach($cases as $c):?><p><strong><?=e($c['number'])?></strong> · <?=e($c['type'])?> · <?=e($c['status'])?></p><?php endforeach;?><?php endif;?></aside></section>
